<script>

/* ================================
   KONFIGURASI
================================ */

const WA_NUMBER = "6283869691636";

const SCRIPT =
'loadstring(game:HttpGet("https://miyako-api.psteamofficial368.workers.dev/"))()';


/* ================================
   WHATSAPP
================================ */

document.querySelectorAll(".wa").forEach(function(button){

  const message =
    button.getAttribute("data-msg") ||
    "Min, Saya Mau Beli script";

  button.href =
    "https://wa.me/" +
    WA_NUMBER +
    "?text=" +
    encodeURIComponent(message);

  button.target = "_blank";
  button.rel = "noopener noreferrer";

});


/* ================================
   SCRIPT PREVIEW & DECRYPT ANIMATION
================================ */

const showScript = document.getElementById("showScript");
const copyScript = document.getElementById("copyScript");
const terminalBox = document.getElementById("terminalBox");
const kode = document.getElementById("kode");
const decryptStatus = document.getElementById("decryptStatus");
const decryptLabel = document.getElementById("decryptLabel");
const decryptPercent = document.getElementById("decryptPercent");
const progressTrack = document.getElementById("progressTrack");
const progressFill = document.getElementById("progressFill");


/* ================================
   GATE: WAJIB JOIN SALURAN DULU
================================ */

const scriptGate = document.getElementById("scriptGate");
const joinGateBtn = document.getElementById("joinGateBtn");

// Gate ini SENGAJA tidak disimpan di localStorage, biar wajib
// klik join saluran lagi tiap kali halaman dibuka/direfresh —
// jadi gak bisa "kebuka otomatis" walau belum join.
function unlockScript(){
  scriptGate.style.display = "none";
  showScript.style.display = "block";
}

joinGateBtn.addEventListener("click", function(){
  setTimeout(unlockScript, 600);
});


const CIPHER_CHARS =
  "アイウエオカキクケコサシスセソタチツテト!<>-_/[]{}=+*^?#ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

const DECRYPT_LABELS = [
  "MENGHUBUNGKAN KE SERVER...",
  "MEMBYPASS KEAMANAN...",
  "MENDEKRIPSI SCRIPT...",
  "MENYUSUN DATA..."
];

function runDecryptEffect(finalText, duration, onDone){

  const total = finalText.length;
  const steps = 46;
  const stepTime = duration / steps;
  let step = 0;

  kode.classList.add("decrypting");
  kode.classList.remove("done");

  const timer = setInterval(function(){

    step++;

    const revealCount = Math.floor((step / steps) * total);

    kode.textContent = finalText
      .split("")
      .map(function(ch, i){
        if(i < revealCount) return ch;
        return CIPHER_CHARS[Math.floor(Math.random() * CIPHER_CHARS.length)];
      })
      .join("");

    const pct = Math.min(100, Math.round((step / steps) * 100));
    progressFill.style.width = pct + "%";
    decryptPercent.textContent = pct + "%";

    const labelIndex = Math.min(
      DECRYPT_LABELS.length - 1,
      Math.floor((step / steps) * DECRYPT_LABELS.length)
    );
    decryptLabel.textContent = DECRYPT_LABELS[labelIndex];

    if(step >= steps){

      clearInterval(timer);

      kode.textContent = finalText;
      kode.classList.remove("decrypting");
      kode.classList.add("done");

      progressFill.style.width = "100%";
      decryptPercent.textContent = "100%";
      decryptLabel.textContent = "SELESAI ✓";

      if(onDone) onDone();

    }

  }, stepTime);

}

showScript.addEventListener("click", function(){

  // Sembunyikan tombol "Klik di sini untuk script nya"
  showScript.style.display = "none";

  // Tampilkan kotak terminal + status decrypt + progress bar
  terminalBox.style.display = "block";
  decryptStatus.style.display = "flex";
  progressTrack.style.display = "block";

  progressFill.style.width = "0%";
  decryptPercent.textContent = "0%";
  decryptLabel.textContent = "MENGHUBUNGKAN KE SERVER...";
  kode.textContent = "";

  // Jalankan animasi decrypt ala hacker/anime selama ~2.6 detik
  runDecryptEffect(SCRIPT, 2600, function(){
    copyScript.style.display = "block";
  });

});


/* ================================
   COPY SCRIPT
================================ */

const toast =
  document.getElementById("toast");

function showToast(message){

  toast.textContent = message;
  toast.classList.add("show");

  setTimeout(function(){
    toast.classList.remove("show");
  },2200);

}

copyScript.addEventListener("click",async function(){

  try{

    await navigator.clipboard.writeText(SCRIPT);

    copyScript.textContent =
      "✓ SCRIPT TERSALIN";

    showToast("✓ Script berhasil disalin");

    setTimeout(function(){

      copyScript.textContent =
        "SALIN SCRIPT";

    },2000);

  }catch(error){

    const area =
      document.createElement("textarea");

    area.value = SCRIPT;
    area.style.position = "fixed";
    area.style.opacity = "0";

    document.body.appendChild(area);

    area.focus();
    area.select();

    try{
      document.execCommand("copy");
      showToast("✓ Script berhasil disalin");
    }catch(e){
      showToast("Gagal menyalin script");
    }

    document.body.removeChild(area);

  }

});


/* ================================
   KOMENTAR PEMBELI (tersimpan, tidak hilang)
================================ */

const COMMENT_KEY = "miyako_comments_v1";
const COMMENT_COOLDOWN_KEY = "miyako_last_comment_time";
const COOLDOWN_MS = 60 * 60 * 1000; // 1 jam

const commentName = document.getElementById("commentName");
const commentText = document.getElementById("commentText");
const submitComment = document.getElementById("submitComment");
const commentList = document.getElementById("commentList");

// ISI dengan URL Realtime Database Firebase kamu, contoh:
// "https://nama-project-default-rtdb.asia-southeast1.firebasedatabase.app"
// Kalau dikosongkan, komentar cuma tersimpan di HP masing-masing.
const FIREBASE_URL = "https://andezvvip-default-rtdb.firebaseio.com";

commentName.maxLength = 30;
commentText.maxLength = 300;

let commentsCache = [];

function localLoad(){
  try{
    const raw = localStorage.getItem(COMMENT_KEY);
    return raw ? JSON.parse(raw) : [];
  }catch(e){
    return [];
  }
}

function localSave(list){
  try{
    localStorage.setItem(COMMENT_KEY, JSON.stringify(list));
  }catch(e){
    // storage tidak tersedia, abaikan
  }
}

async function fetchComments(){
  if(!FIREBASE_URL){
    commentsCache = localLoad();
    return;
  }
  try{
    const base = FIREBASE_URL.replace(/\/+$/, "");
    const res = await fetch(base + '/comments.json?orderBy="ts"&limitToLast=50');
    const data = await res.json();
    commentsCache = (data && !data.error)
      ? Object.values(data).sort(function(a,b){ return a.ts - b.ts; })
      : [];
  }catch(e){
    commentsCache = [];
  }
}

async function postComment(entry){
  if(!FIREBASE_URL){
    const list = localLoad();
    list.push(entry);
    localSave(list);
    return true;
  }
  try{
    const base = FIREBASE_URL.replace(/\/+$/, "");
    const res = await fetch(base + "/comments.json", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify(entry)
    });
    return res.ok;
  }catch(e){
    return false;
  }
}

function renderComments(){

  const list = commentsCache;

  if(list.length === 0){
    commentList.innerHTML =
      '<p class="comment-empty">Belum ada komentar. Jadi yang pertama komen!</p>';
    return;
  }

  commentList.innerHTML = "";

  list.slice().reverse().forEach(function(c){

    const item = document.createElement("div");
    item.className = "review";

    const initial = c.name.charAt(0).toUpperCase();

    const nameEl = document.createElement("div");
    nameEl.className = "review-name";
    nameEl.textContent = c.name;

    const avatarEl = document.createElement("div");
    avatarEl.className = "avatar";
    avatarEl.textContent = initial;

    const userEl = document.createElement("div");
    userEl.className = "user";
    userEl.appendChild(avatarEl);
    userEl.appendChild(nameEl);

    const timeEl = document.createElement("div");
    timeEl.className = "comment-time";
    timeEl.textContent = c.ts
      ? new Date(c.ts).toLocaleDateString("id-ID", {day:"numeric", month:"short", year:"numeric"})
      : c.time;

    const topEl = document.createElement("div");
    topEl.className = "review-top";
    topEl.appendChild(userEl);
    topEl.appendChild(timeEl);

    const textEl = document.createElement("p");
    textEl.textContent = c.text;

    item.appendChild(topEl);
    item.appendChild(textEl);

    commentList.appendChild(item);

  });

}

function getRemainingCooldown(){
  try{
    const last = parseInt(localStorage.getItem(COMMENT_COOLDOWN_KEY) || "0", 10);
    const elapsed = Date.now() - last;
    return Math.max(0, COOLDOWN_MS - elapsed);
  }catch(e){
    return 0;
  }
}

submitComment.addEventListener("click", async function(){

  const remaining = getRemainingCooldown();

  if(remaining > 0){
    const minutesLeft = Math.ceil(remaining / 60000);
    showToast("Tunggu " + minutesLeft + " menit lagi buat komen ya");
    return;
  }

  const name = (commentName.value.trim() || "Anonim").slice(0, 30);
  const text = commentText.value.trim().slice(0, 300);

  if(!text){
    commentText.focus();
    return;
  }

  submitComment.disabled = true;

  const ok = await postComment({
    name: name,
    text: text,
    ts: Date.now()
  });

  submitComment.disabled = false;

  if(!ok){
    showToast("Gagal kirim komentar, coba lagi");
    return;
  }

  try{
    localStorage.setItem(COMMENT_COOLDOWN_KEY, String(Date.now()));
  }catch(e){
    // storage tidak tersedia, abaikan
  }

  commentName.value = "";
  commentText.value = "";

  await fetchComments();
  renderComments();
  showToast("\u2713 Komentar terkirim");

});

fetchComments().then(renderComments);


/* ================================
   COUNTER PENGUNJUNG (butuh FIREBASE_URL)
   Dihitung 1x per HP/browser, refresh tidak menambah.
================================ */

(async function(){

  if(!FIREBASE_URL) return;

  const base = FIREBASE_URL.replace(/\/+$/, "");
  const url = base + "/stats/visits.json";
  const VISIT_KEY = "miyako_visit_counted";

  let alreadyCounted = false;
  try{
    alreadyCounted = localStorage.getItem(VISIT_KEY) === "1";
  }catch(e){}

  try{
    let total;

    if(alreadyCounted){
      const res = await fetch(url);
      total = await res.json();
    }else{
      const res = await fetch(url, {
        method: "PUT",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({".sv": {"increment": 1}})
      });
      if(res.ok){
        try{ localStorage.setItem(VISIT_KEY, "1"); }catch(e){}
      }
      const res2 = await fetch(url);
      total = await res2.json();
    }

    if(typeof total === "number"){
      document.getElementById("visitorCount").textContent =
        total.toLocaleString("id-ID");
      document.getElementById("visitorBadge").style.display = "flex";
    }
  }catch(e){
    // gagal, badge tetap disembunyikan
  }

})();


/* ================================
   SCROLL ANIMATION
================================ */

const observer =
  new IntersectionObserver(

    function(entries){

      entries.forEach(function(entry){

        if(entry.isIntersecting){

          entry.target.classList.add("show");

          observer.unobserve(entry.target);

        }

      });

    },

    {
      threshold:.12,
      rootMargin:"0px 0px -30px 0px"
    }

  );


document
  .querySelectorAll(".reveal")
  .forEach(function(element){

    observer.observe(element);

  });


