/* ================================
   LOADING SCREEN
================================ */

(function(){

  const loader = document.getElementById("loader");
  if(!loader) return;

  const startTime = Date.now();
  const MIN_SHOW = 1800;
  let closed = false;

  function closeLoader(){
    if(closed) return;
    closed = true;
    loader.classList.add("hide");
    setTimeout(function(){ loader.remove(); }, 700);
  }

  function scheduleClose(){
    const wait = Math.max(0, MIN_SHOW - (Date.now() - startTime));
    setTimeout(closeLoader, wait);
  }

  if(document.readyState === "complete"){
    scheduleClose();
  }else{
    window.addEventListener("load", scheduleClose);
  }

  // jaga-jaga kalau ada resource yang lama
  setTimeout(closeLoader, 5000);

})();



/* ================================
   LAYOUT BARU: LOGO, MENU, TESTIMONI, SLOT, SOSMED
================================ */

// Logo dipakai ulang dari gambar loader (tanpa menambah ukuran file)
const LOGO_SRC = document.querySelector("#loader img").src;
document.querySelectorAll("img[data-logo]").forEach(function(i){ i.src = LOGO_SRC; });

// Menu samping (hamburger)
const drawer = document.getElementById("drawer");
