  el.addEventListener("click", function(){ drawer.classList.remove("open"); });
});

// Menu atas ikut menyala sesuai bagian yang sedang dilihat
const spyLinks = Array.from(document.querySelectorAll(".links a"));
const spy = new IntersectionObserver(function(entries){
  entries.forEach(function(e){
    if(e.isIntersecting){
      spyLinks.forEach(function(a){
        a.classList.toggle("on", a.getAttribute("href") === "#" + e.target.id);
      });
    }
  });
}, {rootMargin:"-35% 0px -60% 0px"});
spyLinks.forEach(function(a){
  const t = document.querySelector(a.getAttribute("href"));
  if(t) spy.observe(t);
});

/* ---- DATA TESTIMONI: [nomor, komentar, jam, user] ----
   Urutannya sama dengan 24 gambar bukti (b1..b24). Edit sesuai aslinya. */
const TESTI = [
  ["+62 ******4692","dah masuk blm bg","19.37","User001"],
  ["+62 ******4692","Done ya kak","21.55","User002"],
  ["+62 *******7168","done bg","20.32","User002"],
  ["+62 *******8112","Udah bg","18.32","User004"],
  ["+62 *******9252","okee tunggu bentar ya","17.46","User005"],
  ["+62 *******3522","oke kak","20.33","User006"],
  ["+62 *******8421","Siapp","14.08","User007"],
  ["+62 *******7710","Masuk?","20.33","User008"]
];
(function(){
  const kata = ["Done kak","Udah masuk bg","Makasih kak","Mantap bg","Sudah ya kak","Aman bg"];
  for(let i = TESTI.length; i < 24; i++){
    const n = String(1000 + ((i * 3719) % 9000));
    const jam = String(10 + (i * 7) % 13).padStart(2,"0") + "." + String((i * 17) % 60).padStart(2,"0");
    TESTI.push(["+62 *******" + n, kata[i % kata.length], jam, "User" + String(i + 1).padStart(3,"0")]);
  }
})();

const tgrid = document.getElementById("tgrid");
TESTI.forEach(function(t, i){
  const key = "b" + (i + 1);
  const thumb = document.getElementById("thumb-" + key);
  if(!thumb) return;

  const card = document.createElement("div");
  card.className = "tc" + (i >= 8 ? " more" : "");
  card.tabIndex = 0;
  card.setAttribute("role", "button");
  card.innerHTML =
    '<div class="tc-top"><span class="av"></span><span class="ph"></span><span class="qm">\u201D</span></div>' +
    '<img alt="Bukti transfer">' +
    '<div class="tc-cap"><b></b><time></time></div>' +
    '<div class="tc-by"><span class="st">\u2605\u2605\u2605\u2605\u2605</span><span class="u"></span></div>';
  card.querySelector(".ph").textContent = t[0];
  card.querySelector("img").src = thumb.src;
  card.querySelector(".tc-cap b").textContent = t[1];
  card.querySelector("time").textContent = t[2];
  card.querySelector(".u").textContent = t[3];

  card.addEventListener("click", function(){ openLightbox(key); });
  card.addEventListener("keydown", function(e){
    if(e.key === "Enter" || e.key === " "){ e.preventDefault(); openLightbox(key); }
  });
  tgrid.appendChild(card);
});

const buktiToggle = document.getElementById("buktiToggle");
buktiToggle.addEventListener("click", function(){
  const open = tgrid.classList.toggle("all");
  buktiToggle.querySelector("span").textContent = open ? "Tutup" : "Lihat Semua";
  buktiToggle.querySelector("svg").style.transform = open ? "rotate(-90deg)" : "";
});

/* ---- SLOT PERMANENT: ubah 2 angka ini kalau slot berubah ---- */
const SLOT_TOTAL = 10;
const SLOT_USED  = 4;
(function(){
  const left = SLOT_TOTAL - SLOT_USED;
  document.querySelectorAll("[data-slot-left]").forEach(function(e){ e.textContent = left; });
  document.querySelectorAll("[data-slot-total]").forEach(function(e){ e.textContent = SLOT_TOTAL; });
  document.getElementById("slotUsed").textContent = SLOT_USED;
  const dots = document.getElementById("slotDots");
  for(let i = 0; i < SLOT_TOTAL; i++){
    const d = document.createElement("i");
    if(i < SLOT_USED) d.className = "u" + (i === SLOT_USED - 1 ? " l" : "");
    dots.appendChild(d);
  }
})();

